UPDATE nw_workflow_containers
SET current_draft_revision = #{nextRevision},
    status = 'draft',
    updated_at = now()
WHERE id = #{containerId}
  AND tenant_id = #{tenantId}
  AND current_draft_revision = #{expectedRevision}
  AND status IN ('draft','published')

UPDATE nw_workflow_containers
SET current_draft_revision = #{nextRevision},
    status = 'draft',
    updated_at = now()
WHERE id = #{containerId}
  AND tenant_id = #{tenantId}
  AND status = 'published'
  AND current_draft_revision = #{expectedRevision}

UPDATE nw_workflow_containers
SET active_definition_version_id = #{definitionVersionId},
    status = 'published',
    updated_at = now()
WHERE id = #{containerId}
  AND tenant_id = #{tenantId}
  AND current_draft_revision = #{expectedRevision}
